"use client";

import { useEffect, useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Activity, Server, Zap, Cpu, X, Database, Search, Code, CheckCircle, Clock } from "lucide-react";

// --- Data Models ---
const systemStatus = [
  { id: "api-github", name: "GitHub API", status: "green" },
  { id: "api-openai", name: "OpenAI API", status: "green" },
  { id: "api-claude", name: "Claude API", status: "green" },
  { id: "mcp-gitkraken", name: "MCP GitKraken", status: "yellow" },
  { id: "mcp-notebooklm", name: "MCP NotebookLM", status: "green" },
  { id: "mcp-autoresearch", name: "MCP AutoResearch", status: "red" },
  { id: "tool-iceberg", name: "Iceberg Lake", status: "critical" },
  { id: "bot-james", name: "James Guardian", status: "green" }
];

const agentsList = [
  { id: "a1", name: "DkZ Researcher", status: "doing", task: "Deep-Scraping Web Data", icon: Search, color: "#00ff88", x: 150, y: 150 },
  { id: "a2", name: "DkZ Writer", status: "wait", task: "Awaiting Research Output", icon: Code, color: "#FFB800", x: 450, y: 200 },
  { id: "a3", name: "DkZ SEO", status: "result", task: "Idle - Ready for Review", icon: Activity, color: "#55ACEE", x: 750, y: 150 },
  { id: "a4", name: "CodeRabbit", status: "wait", task: "Monitoring Repositories", icon: CheckCircle, color: "#FFB800", x: 300, y: 400 },
  { id: "a5", name: "DkZ Architekt", status: "doing", task: "Constructing Nanobot Engine", icon: Cpu, color: "#fa1e4e", x: 600, y: 400 }
];

export default function SwarmDashboard() {
  const [agents, setAgents] = useState(agentsList);
  const [selectedAgent, setSelectedAgent] = useState<any>(null);
  const [view, setView] = useState<"matrix" | "kanban">("matrix");
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // --- Particle Engine (React + Canvas) ---
  useEffect(() => {
    if (view !== "matrix" || !canvasRef.current) return;
    
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let particles: any[] = [];
    const PARTICLE_COUNT = 300;
    
    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if(parent) {
        canvas.width = parent.clientWidth;
        canvas.height = parent.clientHeight;
      }
    };
    resizeCanvas();
    window.addEventListener("resize", resizeCanvas);

    // Initialize particles
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      particles.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        vx: (Math.random() - 0.5),
        vy: (Math.random() - 0.5),
        size: Math.random() * 2 + 0.5,
        life: Math.random() * 100,
        targetNode: null
      });
    }

    let animationFrameId: number;

    const render = () => {
      ctx.fillStyle = "rgba(0, 0, 0, 0.15)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Draw Connections
      ctx.lineWidth = 1.5;
      agents.forEach(a1 => {
        agents.forEach(a2 => {
          if (a1.id !== a2.id && Math.hypot(a1.x - a2.x, a1.y - a2.y) < 350) {
            ctx.beginPath();
            ctx.moveTo(a1.x, a1.y);
            ctx.lineTo(a2.x, a2.y);
            
            if (a1.status === "doing" && a2.status === "doing") {
              ctx.strokeStyle = `rgba(250, 30, 78, ${0.4 + Math.sin(Date.now() * 0.005) * 0.2})`;
              ctx.setLineDash([5, 10]);
              ctx.lineDashOffset = -Date.now() * 0.02;
            } else {
              ctx.strokeStyle = "rgba(255, 255, 255, 0.05)";
              ctx.setLineDash([]);
            }
            ctx.stroke();
          }
        });
      });
      ctx.setLineDash([]);

      // Update & Draw Particles
      particles.forEach(p => {
        // Find target
        if (p.targetNode) {
          const dx = p.targetNode.x - p.x;
          const dy = p.targetNode.y - p.y;
          const dist = Math.hypot(dx, dy);
          
          if (dist > 25) {
            p.vx += dx * 0.001;
            p.vy += dy * 0.001;
            p.vx *= 0.95;
            p.vy *= 0.95;
          } else {
            p.vx += (Math.random() - 0.5) * 0.5;
            p.vy += (Math.random() - 0.5) * 0.5;
            p.vx *= 0.8;
            p.vy *= 0.8;
          }
        } else {
          p.x += p.vx;
          p.y += p.vy;
          if (p.x < 0 || p.x > canvas.width) p.vx *= -1;
          if (p.y < 0 || p.y > canvas.height) p.vy *= -1;
        }

        p.x += p.vx;
        p.y += p.vy;
        
        p.life--;
        if (p.life <= 0) {
          const activeNodes = agents.filter(n => n.status === "doing");
          if (activeNodes.length > 0 && Math.random() > 0.4) {
            p.targetNode = activeNodes[Math.floor(Math.random() * activeNodes.length)];
          } else {
            p.targetNode = null;
          }
          p.life = Math.random() * 200 + 50;
        }

        ctx.fillStyle = p.targetNode ? p.targetNode.color : "rgba(255,255,255,0.2)";
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
      });

      // Draw Nodes
      agents.forEach(n => {
        const isActive = n.status === "doing";
        ctx.beginPath();
        ctx.arc(n.x, n.y, isActive ? 8 + Math.sin(Date.now()*0.005)*2 : 5, 0, 2 * Math.PI);
        ctx.fillStyle = isActive ? "#fff" : "rgba(255,255,255,0.3)";
        ctx.shadowBlur = isActive ? 15 : 0;
        ctx.shadowColor = n.color;
        ctx.fill();
        ctx.shadowBlur = 0;
        
        ctx.font = "600 12px Inter";
        ctx.fillStyle = "rgba(255,255,255,0.9)";
        ctx.textAlign = "center";
        ctx.fillText(n.name, n.x, n.y + (isActive ? 30 : 20));
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener("resize", resizeCanvas);
      cancelAnimationFrame(animationFrameId);
    };
  }, [view, agents]);

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    
    const clickedNode = agents.find(n => Math.hypot(n.x - mx, n.y - my) < 30);
    if (clickedNode) {
      setSelectedAgent(clickedNode);
    }
  };

  const triggerEvent = () => {
    setAgents(prev => prev.map(a => 
      a.id === "a2" ? { ...a, status: "doing", task: "Writing Draft (Triggered)" } : a
    ));
  };

  return (
    <div className="relative min-h-screen text-dkz-bg">
      {/* 8K Video Background */}
      <video 
        autoPlay 
        loop 
        muted 
        playsInline 
        className="fixed top-0 left-0 w-full h-full object-cover z-[-2] opacity-60 saturate-150 contrast-125"
      >
        <source src="https://assets.codepen.io/3364143/7btrrd.mp4" type="video/mp4" />
      </video>
      <div className="fixed top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_center,transparent_0%,var(--color-dkz-bg)_100%)] z-[-1] pointer-events-none" />

      {/* Header */}
      <header className="flex justify-between items-center px-6 py-4 bg-[#060608]/40 backdrop-blur-xl border-b border-white/10 shadow-[0_4px_30px_rgba(0,0,0,0.5)]">
        <div className="flex items-center gap-4">
          <span className="text-dkz-accent font-semibold cursor-pointer">← Hub</span>
          <h1 className="text-lg font-bold text-white">🤖 Swarm Mission Control <span className="text-dkz-accent">PRO</span></h1>
        </div>
        <span className="text-sm text-gray-400">Next.js Edition v1.0</span>
      </header>

      {/* Main Grid */}
      <main className="p-4 md:p-6 grid grid-cols-1 lg:grid-cols-[280px_1fr_340px] gap-5 h-[calc(100vh-70px)]">
        
        {/* Left: System Health */}
        <div className="glass-panel rounded-xl flex flex-col p-5">
          <h2 className="text-sm font-bold uppercase tracking-wider text-transparent bg-clip-text bg-gradient-to-r from-white to-gray-500 border-b border-white/10 pb-3 mb-4 flex items-center gap-2">
            <Server size={16}/> System Health
          </h2>
          <ul className="flex-1 overflow-y-auto space-y-1 pr-2">
            {systemStatus.map(s => (
              <li key={s.id} className="flex items-center p-2 rounded-lg hover:bg-white/5 transition-colors">
                <div className={`w-2.5 h-2.5 rounded-full mr-3 shadow-[0_0_10px_currentColor] 
                  ${s.status === "green" ? "bg-dkz-green text-dkz-green" : 
                    s.status === "yellow" ? "bg-dkz-yellow text-dkz-yellow" : 
                    s.status === "red" ? "bg-dkz-red text-dkz-red" : 
                    "bg-dkz-red text-dkz-red animate-pulse shadow-[0_0_20px_currentColor]"}`} 
                />
                <span className="font-mono text-sm text-gray-300">{s.name}</span>
              </li>
            ))}
          </ul>
          <button 
            onClick={triggerEvent}
            className="mt-4 py-2 px-4 rounded-lg text-xs font-semibold border border-dkz-green/50 text-dkz-green bg-dkz-green/10 hover:bg-dkz-green hover:text-black transition-all shadow-[0_0_15px_rgba(0,255,136,0.2)] flex items-center justify-center gap-2"
          >
            <Zap size={14} /> Trigger Nanobot Push
          </button>
        </div>

        {/* Center: Engine View */}
        <div className="glass-panel rounded-xl flex flex-col overflow-hidden relative">
          <div className="p-4 border-b border-white/10 flex justify-between items-center bg-black/20">
            <h2 className="text-sm font-bold uppercase tracking-wider text-transparent bg-clip-text bg-gradient-to-r from-white to-gray-500">
              Swarm Orchestration
            </h2>
            <div className="flex gap-2">
              <button 
                onClick={() => setView("kanban")}
                className={`px-3 py-1.5 rounded-md text-xs font-semibold transition-all ${view === "kanban" ? "bg-dkz-accent/20 text-dkz-accent border border-dkz-accent shadow-[0_0_15px_rgba(250,30,78,0.3)]" : "bg-white/5 text-gray-400 border border-white/10"}`}
              >Kanban</button>
              <button 
                onClick={() => setView("matrix")}
                className={`px-3 py-1.5 rounded-md text-xs font-semibold transition-all ${view === "matrix" ? "bg-dkz-accent/20 text-dkz-accent border border-dkz-accent shadow-[0_0_15px_rgba(250,30,78,0.3)]" : "bg-white/5 text-gray-400 border border-white/10"}`}
              >Nanobot Matrix</button>
            </div>
          </div>
          
          <div className="flex-1 relative">
            {view === "matrix" ? (
              <motion.canvas 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                ref={canvasRef} 
                className="absolute inset-0 w-full h-full cursor-crosshair"
                onClick={handleCanvasClick}
              />
            ) : (
              <motion.div 
                initial={{ opacity: 0, scale: 0.98 }}
                animate={{ opacity: 1, scale: 1 }}
                className="absolute inset-0 p-4 grid grid-cols-4 gap-4"
              >
                {/* Simple Kanban Placeholder */}
                {['To Do', 'Doing', 'Wait', 'Done'].map((col, idx) => (
                  <div key={col} className="bg-black/40 border border-white/5 rounded-xl p-3 flex flex-col gap-3">
                    <div className="text-xs font-bold text-gray-400 uppercase text-center">{col}</div>
                    {idx === 1 && <div className="glass-card p-3 rounded-lg text-xs border-l-2 border-l-dkz-accent">Draft Next.js Component</div>}
                    {idx === 2 && <div className="glass-card p-3 rounded-lg text-xs border-l-2 border-l-dkz-blue">CodeRabbit Review</div>}
                  </div>
                ))}
              </motion.div>
            )}
          </div>
        </div>

        {/* Right: Agent List */}
        <div className="glass-panel rounded-xl flex flex-col p-5">
          <h2 className="text-sm font-bold uppercase tracking-wider text-transparent bg-clip-text bg-gradient-to-r from-white to-gray-500 border-b border-white/10 pb-3 mb-4">
            👥 Active Nanobots
          </h2>
          <div className="flex-1 overflow-y-auto space-y-3 pr-2">
            {agents.map(a => {
              const Icon = a.icon;
              return (
                <motion.div 
                  layoutId={`agent-${a.id}`}
                  key={a.id} 
                  className="bg-black/30 border border-white/5 hover:border-white/20 rounded-xl p-3 transition-colors cursor-pointer group"
                  onClick={() => setSelectedAgent(a)}
                >
                  <div className="flex justify-between items-center mb-2">
                    <div className="flex items-center gap-2">
                      <Icon size={14} color={a.color} />
                      <span className="font-semibold text-sm text-gray-200">{a.name}</span>
                    </div>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wide border ${
                      a.status === "doing" ? "bg-dkz-green/10 text-dkz-green border-dkz-green/30" :
                      a.status === "wait" ? "bg-dkz-yellow/10 text-dkz-yellow border-dkz-yellow/30" :
                      "bg-dkz-blue/10 text-dkz-blue border-dkz-blue/30"
                    }`}>
                      {a.status}
                    </span>
                  </div>
                  <div className="text-xs text-gray-400 font-mono">{a.task}</div>
                </motion.div>
              );
            })}
          </div>
        </div>
      </main>

      {/* Modal Popup (Framer Motion) */}
      <AnimatePresence>
        {selectedAgent && (
          <>
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setSelectedAgent(null)}
              className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40"
            />
            <motion.div 
              layoutId={`agent-${selectedAgent.id}`}
              initial={{ opacity: 0, scale: 0.9, y: 20, x: "-50%" }}
              animate={{ opacity: 1, scale: 1, y: "-50%", x: "-50%" }}
              exit={{ opacity: 0, scale: 0.95, y: -20, x: "-50%" }}
              className="fixed top-1/2 left-1/2 w-96 bg-[#0a0a0f]/80 backdrop-blur-3xl border border-dkz-accent/40 rounded-2xl shadow-[0_20px_60px_rgba(0,0,0,0.8),0_0_30px_rgba(250,30,78,0.2)] p-6 z-50 text-white"
            >
              <button 
                onClick={() => setSelectedAgent(null)}
                className="absolute top-4 right-4 text-gray-400 hover:text-white"
              >
                <X size={20} />
              </button>
              
              <div className="flex items-center gap-3 mb-6">
                <selectedAgent.icon size={24} color={selectedAgent.color} />
                <h3 className="text-xl font-bold text-dkz-accent">{selectedAgent.name}</h3>
              </div>

              <div className="space-y-3 font-mono text-xs">
                <div className="flex justify-between pb-2 border-b border-white/5">
                  <span className="text-gray-400">Status</span>
                  <span style={{ color: selectedAgent.color }} className="font-bold uppercase">{selectedAgent.status}</span>
                </div>
                <div className="flex justify-between pb-2 border-b border-white/5">
                  <span className="text-gray-400">Current Task</span>
                  <span className="text-gray-200">{selectedAgent.task}</span>
                </div>
                <div className="flex justify-between pb-2 border-b border-white/5">
                  <span className="text-gray-400">Confidence Score</span>
                  <span className="text-dkz-yellow">{(Math.random() * 15 + 84).toFixed(1)}%</span>
                </div>
                <div className="flex justify-between pb-2 border-b border-white/5">
                  <span className="text-gray-400">Memory Usage</span>
                  <span>{Math.floor(Math.random() * 200 + 50)} MB</span>
                </div>
                <div className="flex justify-between pb-2 border-b border-white/5">
                  <span className="text-gray-400">Last Event</span>
                  <span className="text-dkz-blue">sys_processing_stream</span>
                </div>
              </div>

              <button className="mt-6 w-full py-2.5 rounded-lg bg-dkz-accent/10 border border-dkz-accent/50 text-dkz-accent hover:bg-dkz-accent hover:text-white transition-all shadow-[0_0_15px_rgba(250,30,78,0.3)] flex justify-center items-center gap-2">
                <Activity size={16} /> Optimize Nanobot Matrix
              </button>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </div>
  );
}
